Ниже приведен пример функции C++, которая принимает ссылку на std::string, содержащую текст в формате уценки, и возвращает std::string, содержащий текст в формате HTML.

```c++
#include <iostream>
#include <string>
#include <regex>

std::string convertMarkdownToHtml(std::string& input_str) {
    std::string output_str;

    // Замена уценок на теги `<strong>` и `<em>`
    std::regex regex1("\\*([^*]+)\\*");
    std::smatch match;

    while (std::regex_search(input_str, match, regex1)) {
        output_str += "<strong>";
        output_str += match[1];
        output_str += "</strong>";
        input_str = match.position(0) + match.length(0) == input_str.size() ? "" : input_str.substr(match.position(0) + match.length(0));
    }

    std::regex regex2("__([^_]+)__");
    while (std::regex_search(input_str, match, regex2)) {
        output_str += "<em>";
        output_str += match[1];
        output_str += "</em>";
        input_str = match.position(0) + match.length(0) == input_str.size() ? "" : input_str.substr(match.position(0) + match.length(0));
    }

    return output_str;
}

int main() {
    std::string input_str = "Вот пример **стронного** текста и __подчёркнутого__ текста.";

    std::string output_str = convertMarkdownToHtml(input_str);

    std::cout << "Входная строка: " << input_str << std::endl;
    std::cout << "Выходная строка: " << output_str << std::endl;

    return 0;
}
```

Пример вывода:

```
Входная строка: Вот пример **стронного** текста и __подчёркнутого__ текста.
Выходная строка: <strong>Вот пример</strong> <em>стронного</em> текста и <strong>подчёркнутого</strong> текста.
```

