```c
#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#include <SDL2/SDL.h>

// Устанавливаем константы
#define WINDOW_WIDTH 800
#define WINDOW_HEIGHT 600
#define FRAMES_PER_SECOND 60

// Определение цветов
SDL_Color GREEN = {0, 128, 0};
SDL_Color RED = {255, 0, 0};

// Определение типов данных
typedef struct Snake {
    int x, y;
    int len;
    SDL_Rect *body;
} Snake;

typedef struct Fruit {
    int x, y;
} Fruit;

typedef struct Wall {
    int x1, y1;
    int x2, y2;
} Wall;

// Функции
void initSDL();
void closeSDL();
void handleEvents(SDL_Event *event);
void renderScene(Snake *snake, Fruit *fruit, Wall *walls);
void updateScene(Snake *snake, Fruit *fruit, Wall *walls);

int main(int argc, char **argv) {
    // Инициализация SDL
    initSDL();

    // Создание объектов
    Snake snake = {{400, 300}, 3, NULL};
    Fruit fruit = {rand() % WINDOW_WIDTH, rand() % WINDOW_HEIGHT};
    Wall walls[4] = {{0, 0}, {WINDOW_WIDTH, 0},
                    {WINDOW_WIDTH, WINDOW_HEIGHT},
                    {0, WINDOW_HEIGHT}};

    bool running = true;

    // Основной цикл
    while (running) {
        SDL_Event event;
        while (SDL_PollEvent(&event)) {
            handleEvents(&event);
        }

        updateScene(&snake, &fruit, walls);
        renderScene(&snake, &fruit, walls);
        SDL_Delay(1000 / FRAMES_PER_SECOND);
    }

    closeSDL();

    return 0;
}

void initSDL() {
    if (SDL_Init(SDL_INIT_VIDEO) < 0) {
        printf("Ошибка инициализации SDL: %s\n", SDL_GetError());
        exit(EXIT_FAILURE);
    }

    SDL_Window *window = SDL_CreateWindow("Snake",
                                           SDL_WINDOWPOS_CENTERED,
                                           SDL_WINDOWPOS_CENTERED,
                                           WINDOW_WIDTH, WINDOW_HEIGHT,
                                           SDL_WINDOW_SHOWN);

    if (!window) {
        printf("Ошибка создания окна SDL: %s\n", SDL_GetError());
        exit(EXIT_FAILURE);
    }

    SDL_Renderer *renderer = SDL_CreateRenderer(window, -1, SDL_RENDERER_ACCELERATED);
    if (!renderer) {
        printf("Ошибка создания рендерера SDL: %s\n", SDL_GetError());
        exit(EXIT_FAILURE);
    }
}

void closeSDL() {
    SDL_DestroyRenderer(gRenderer);
    SDL_DestroyWindow(gWindow);
    SDL_Quit();
}

void handleEvents(SDL_Event *event) {
    switch (event->type) {
        case SDL_QUIT:
            gRunning = false;
            break;
        case SDL_KEYDOWN:
            switch (event->key.keysym.sym) {
                case SDLK_UP:
                    gSnake.dirY = -1;
                    gSnake.dirX = 0;
                    break;
                case SDLK_DOWN:
                    gSnake.dirY = 1;
                    gSnake.dirX = 0;
                    break;
                case SDLK_LEFT:
                    gSnake.dirX = -1;
                    gSnake.dirY = 0;
                    break;
                case SDLK_RIGHT:
                    gSnake.dirX = 1;
                    gSnake.dirY = 0;
                    break;
            }
            break;
    }
}

void renderScene(Snake *snake, Fruit *fruit, Wall *walls) {
    SDL_SetRenderDrawColor(gRenderer, 0, 0, 0, SDL_ALPHA_OPAQUE);
    SDL_RenderClear(gRenderer);

    // Отрисовка змейки
    for (int I = 0; I < snake->len; i++) {
        SDL_Rect r = {(i % 20) * 40 + 10, (i / 20) * 30 + 10, 20, 20};
        SDL_SetTextureColorMod(gTextureSnake, GREEN.r, GREEN.g, GREEN.b);
        SDL_RenderCopy(gRenderer, gTextureSnake, NULL, &r);
    }

    // Отрисовка фрукта
    SDL_Rect r = {fruit->x, fruit->y, 20, 20};
    SDL_SetTextureColorMod(gTextureFruit, RED.r, RED.g, RED.b);
    SDL_RenderCopy(gRenderer, gTextureFruit, NULL, &r);

    // Отрисовка стен
    for (int I = 0; I < 4; i++) {
        SDL_RenderFillRect(gRenderer, &(walls[i].x1), &(walls[i].y1));
    }

    SDL_RenderPresent(gRenderer);
}

void updateScene(Snake *snake, Fruit *fruit, Wall *walls) {
    // Движение змейки
    int newX = snake->x + snake->dirX * 20;
    int newY = snake->y + snake->dirY * 30;

    if (newX < 0 || newX >= WINDOW_WIDTH || newY < 0 || newY >= WINDOW_HEIGHT) {
        gRunning = false;
    } else {
        bool hitWall = false;
        for (int I = 0; I < 4; i++) {
            if ((newX >= walls[i].x1 && newX <= walls[i].x2) &&
                (newY >= walls[i].y1 && newY <= walls[i].y2)) {
                hitWall = true;
                break;
            }
        }

        if (!hitWall) {
            int tailX = snake->body[snake->len-1].x;
            int tailY = snake->body[snake->len-1].y;
            snake->body[snake->len++] = (SDL_Rect){tailX, tailY, 20, 20};
            if (newX == fruit->x && newY == fruit->y) {
                gScore++;
                fruit->x = rand() % WINDOW_WIDTH;
                fruit->y = rand() % WINDOW_HEIGHT;
            }
        } else {
            gRunning = false;
        }

        snake->x = newX;
        snake->y = newY;
    }
}
